INSERT INTO board_schemas (id, name, version, description, schema_json, canonical_json, by_actor, created_at) VALUES ('git-commit@1', 'git-commit', 1, 'A Git commit, by its full SHA and the first line of its message.', '{"type":"object","additionalProperties":false,"required":["sha","title"],"properties":{"sha":{"type":"string","pattern":"^(?:[0-9a-f]{40}|[0-9a-f]{64})$","description":"Full lowercase commit SHA"},"title":{"type":"string","minLength":1,"maxLength":1024}}}', '{"additionalProperties":false,"properties":{"sha":{"description":"Full lowercase commit SHA","pattern":"^(?:[0-9a-f]{40}|[0-9a-f]{64})$","type":"string"},"title":{"maxLength":1024,"minLength":1,"type":"string"}},"required":["sha","title"],"type":"object"}', 'board', '2026-11-22T00:00:00.000Z');
INSERT INTO board_schemas (id, name, version, description, schema_json, canonical_json, by_actor, created_at) VALUES ('vercel-deployment@1', 'vercel-deployment', 1, 'A Vercel deployment, by its URL and optionally the commit it was built from.', '{"type":"object","additionalProperties":false,"required":["url"],"properties":{"url":{"type":"string","format":"uri","pattern":"^https://","maxLength":2048},"gitSha":{"type":"string","pattern":"^(?:[0-9a-f]{40}|[0-9a-f]{64})$","description":"Full lowercase commit SHA"}}}', '{"additionalProperties":false,"properties":{"gitSha":{"description":"Full lowercase commit SHA","pattern":"^(?:[0-9a-f]{40}|[0-9a-f]{64})$","type":"string"},"url":{"format":"uri","maxLength":2048,"pattern":"^https://","type":"string"}},"required":["url"],"type":"object"}', 'board', '2026-11-22T00:00:00.000Z');
